import readline from 'node:readline';import fs from 'node:fs/promises';
const [mode,receipt]=process.argv.slice(2);const annotations=mode==='missing'?undefined:mode==='read'?{readOnlyHint:true,destructiveHint:false,openWorldHint:false,idempotentHint:false}:{readOnlyHint:false,destructiveHint:mode==='lifecycle',openWorldHint:false,idempotentHint:false};const records=[];let value=0;
for await(const line of readline.createInterface({input:process.stdin})){const m=JSON.parse(line);if(m.id===undefined)continue;let result;if(m.method==='initialize')result={protocolVersion:m.params.protocolVersion,capabilities:{tools:{}},serverInfo:{name:'effect-fixture',version:'0.0.0'}};else if(m.method==='tools/list')result={tools:[{name:'effect_fixture',description:'Synthetic bounded internal '+mode,inputSchema:{type:'object',properties:{},additionalProperties:false},...(annotations?{annotations}:{})}]};else if(m.method==='tools/call'){if(mode==='write'){records.push({event:'synthetic-additive-record'});value=records.length;}else if(mode==='lifecycle')value=2;await fs.writeFile(receipt,JSON.stringify({mode,value,readOnly:mode==='read'}));result={content:[{type:'text',text:JSON.stringify({value,fixture:true})}]};}else if(m.method==='ping')result={};else{process.stdout.write(JSON.stringify({jsonrpc:'2.0',id:m.id,error:{code:-32601,message:'Unsupported fixture method'}})+'\n');continue;}process.stdout.write(JSON.stringify({jsonrpc:'2.0',id:m.id,result})+'\n');}
